INSERT INTO kpi_threshold VALUES (1, 1, 'default', '>=95%; high-risk/regulated/Crown-Jewel =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (2, 2, 'default', '>=90%; regulated/customer-impacting =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (3, 3, 'default', '0 leakage cases involving regulated/Crown-Jewel data; every event with RCA and control update; assess the total number of confirmed cases against the cap documented in the risk appetite — an increase over the previous period is Amber, exceeding the risk-appetite cap is Red', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (4, 4, 'default', '>=80% initially; public/high-impact use cases =100% before production approval', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (5, 5, 'default', '100% for all autonomous AI agents/automations in production or pilot (productive and high-impact autonomous actions included; for them, the gate is additionally a go-live condition)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (6, 6, 'default', '>=90%; channels carrying regulated data =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (7, 7, 'default', '>=95%; production/high-risk =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (8, 8, 'default', 'Overall rate across all reported/decision-relevant metrics >=95%; board/P0/P1 =100%; no metric without an accountable role/formula/evidence', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (9, 9, 'default', '0% (0 cases of unexplained material denominator drift) across all denominator-based metrics in scope; every case on board/P0 metrics is an immediately escalation-mandatory finding', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (10, 10, 'default', '100% blocked; 0 unblocked Green statuses (unblocked green) below the minimum threshold', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (11, 11, 'default', '>=90%; P0 threshold breaches =100% within the defined governance SLA', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (12, 12, 'default', '>=95%; regulatory/board evidence =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (13, 13, 'default', '>=80% annually; Tier-1 controls >=95%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (14, 14, 'default', 'Board/P0 =100% quarterly; all active metrics >=95% annually', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (15, 15, 'default', 'Target: >70%; Amber: 40-70%; Red: <40%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (16, 16, 'default', 'Target: >95%; Amber: 80-95%; Red: <80%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (17, 17, 'default', 'Target: median < 5 min; P90 < 30 min; adjust per severity; Amber: median 5-15 min or P90 30-60 min; Red: median > 15 min or P90 > 60 min', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (18, 18, 'default', 'Target: <10%; Amber: 10-25%; Red: >25%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (19, 19, 'default', 'Target: <2%; Amber: 2-5%; Red: >5%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (20, 20, 'default', 'Target: 60-80%; Amber: 40 to <60% or >80 to 90%; Red: <40% or >90%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (21, 21, 'default', 'Target: >40% improvement; Amber: 20-40%; Red: <20% or declining. Assessment per severity class against the same band; for the aggregated management view, the worst (lowest) severity value counts.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (22, 22, 'default', 'Target: 100%; Amber: 95 to <100%; Red: <95%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (23, 23, 'default', 'Target: 100%; Amber: 80 to <100%; Red: <80%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (24, 24, 'default', 'Target: <1%; Amber: 1-3%; Red: >3%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (25, 25, 'default', 'Target: detection logic active and calibrated; the reported rate is plausible against the threat landscape (rate > 0% or a value of 0% is explained by demonstrably absent attack attempts) and the trend is stable or explainable; Amber: reported rate declining despite a rising threat landscape, or an unexplained trend break; Red: no detection logic productive - the rate is structurally 0% or not computable', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (26, 26, 'default', 'Target: stable or rising trend, measured against the staffing baseline; Amber: stagnating; Red: declining or below the investment threshold', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (27, 27, 'default', '>=95%; Crown-Jewel/Internet-facing/API =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (28, 28, 'default', '>=95%; Crown-Jewel releases =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (29, 29, 'default', '>=90%; Crown-Jewel =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (30, 30, 'default', '>=95%; critical apps =100%; scan freshness <=30 days before the as-of date (period_end) or per build', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (31, 31, 'default', 'Critical findings on Tier-0 apps <72h and on internet-facing apps <7 days (unweighted exposure hours per finding); risk-weighted hours sum: falling trend', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (32, 32, 'default', '>=95%; Crown-Jewel/customer-facing =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (33, 33, 'default', 'Critical, reachable, and actively exploited dependencies: remediation/isolation <72h; KEV-equivalent =0 open over SLA; percentage value: falling trend', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (34, 34, 'default', '>=90% short-term; Crown-Jewel builds =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (35, 35, 'default', '>=95%; production-deploy paths =100% (subset of the privileged CI/CD paths in the denominator that deploy directly to production; flagged via the documented privilege classification)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (36, 36, 'default', 'P50 (reported) <24h; P90 (displayed) <72h; critical secrets invalidated (revocation/rotation) <24h; p95 <72h; falling recurrence trend (recurrence_count of the current period < recurrence_count of the previous period)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (37, 37, 'default', '>=90%; internet-facing/regulated APIs =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (38, 38, 'default', '<2%; critical releases =0 without CISO/owner sign-off', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (39, 39, 'default', '>=80% initially; >=95% for internet-facing critical apps', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (40, 40, 'default', '<2%; critical workloads =0 unauthorized drift', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (41, 41, 'default', '>=95% across all critical deployments; Crown-Jewel/production deploys =100% — measured as a separate sub-rate with numerator and denominator analogous to the main formula, restricted to deployments with the Crown-Jewel/production criticality flag.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (42, 42, 'default', '>=98%; 100% for Crown Jewels and internet-facing assets', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (43, 43, 'default', 'Target (Green): overall share of unknown assets at or below the tolerance value approved via the versioned risk-appetite statement and trending toward 0; Amber: tolerance value exceeded by up to 25%; Red: tolerance value exceeded by more than 25% — the bands are risk_appetite_bound, not to be derived statistically. Hard gates (override the band rating, no Green on a gate breach): 0 on Tier-0/Tier-1; secondary condition: P90 of the remediation time of unknown assets <7 days (measured per asset from first_seen_timestamp to remediation_timestamp: inventoried or quarantined)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (44, 44, 'default', '>=98%; Tier-0/Tier-1 =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (45, 45, 'default', '>=95%; Crown-Jewel =100%; freshness <=90 days', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (46, 46, 'default', '>=95%; Tier-0/Tier-1 >=98%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (47, 47, 'default', 'Target (Green): overall rate of unauthorized software executions at or below the tolerance value set locally with documented approval and trending toward 0; Amber: tolerance value exceeded by up to 25%; Red: tolerance value exceeded by more than 25% — bands: guidance in the guide; local thresholds with documented approval, not to be derived statistically. Hard gate (overrides the band rating, no Green on a gate breach): 0 on Tier-0/Tier-1', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (48, 48, 'default', 'Target (Green): <=5% unsupported/EOL share; Amber: >5% to <=10%; Red: >10% — the bands are risk_appetite_bound and must be approved via a versioned risk-appetite statement, not derived statistically. Additional hard gates (override the band rating, no Green on a gate breach): 0 internet-facing/Tier-0; only approved exceptions; secondary condition: P90 of the remediation time <90 days (measured per object from eol_confirmed_timestamp to remediation_timestamp: replacement, isolation, or approved exception)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (49, 49, 'default', '<2% overall; 0 critical unknown assets', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (50, 50, 'default', '>=95%; no unmanaged devices in sensitive segments (sensitive = segments classified as sensitive in the versioned network zone concept of the scope)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (51, 51, 'default', '100% for Tier-0/Tier-1; update after a major change (per the versioned change classification scheme of the scope) and quarterly (the last update is at most 90 calendar days before the assessment as-of date, the period end)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (52, 52, 'default', 'Target: 0 for productive internet exposures; Amber: 1-5; Red: >5 or a critical service unknown', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (53, 53, 'default', 'Target: increase <=25% versus the reference base and all new exposures clarified (owner and approval documented via evidence_ref); Amber: increase >25% to <=50% versus the reference base; Red: increase >50% versus the reference base or at least one exposure unclarified at the as-of date (without owner_id or without a documented approval). Reference base = the rate (count per day) of the immediately preceding reporting period of the same length; without an available previous period, the status is provisional.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (54, 54, 'default', 'Target: 0; Amber: 1 with an exception; Red: >1 or without an exception', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (55, 55, 'default', 'Target: 0; Amber: 1 without sensitive data; Red: >1 or sensitive data', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (56, 56, 'default', 'Target: 0% (no weighted certificate defects in scope) and no certificate of a critical asset (criticality = high/critical) affected; Amber: >0% to <=5%, provided no certificate of a critical asset is affected by a defect; Red: >5% or at least one certificate of a critical asset expires in <30 days or is defective (weak algorithm, unknown owner, or hostname mismatch).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (57, 57, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (58, 58, 'default', 'Target: every counted exposure is approved and controlled and the count lies within the target inventory of approved exposures documented and versioned in the risk appetite; Amber: no Red criterion, but at least one exposure with incomplete controls or a count above the target inventory; Red: at least one unknown or unapproved exposure. The status is derived deterministically from the documented approval and control status (status field) of the counted exposures and from the reconciliation of the count against the target inventory; check order: Red before Amber before Target.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (59, 59, 'default', 'Target: no increase >20% versus the previous period and all critical apps in governance - a falling trend is the aim; Amber: no Red criterion, but an increase >20% versus the previous period or at least one critical app outside governance; Red: at least one critical app without owner/IAM. Check order: Red before Amber before Target.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (60, 60, 'default', 'Target: 0 unclarified entries; Amber: 1-5 unclarified entries, none of them a critical subdomain; Red: >5 unclarified entries or at least one unclarified entry of a critical subdomain. Check order: Red before Amber before Target; criticality per the criticality field of the individual record.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (61, 61, 'default', 'Target: 0 counted cases - no third-party asset with a risk_score at or above the documented risk threshold and all third-party assets with a substantiated owner (owner_id), contract (contract_ref), controls (control_status), and evidence (evidence_ref); Amber: at least one counted case, none of them a critical asset (criticality) without a contract or owner; Red: at least one critical asset (criticality) without a contract (contract_ref) or owner (owner_id). Check order: Red before Amber before Target.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (62, 62, 'default', 'Target: overall value <= 20 score points and no critical exposure (no individual risk value >= 80); Amber: overall value > 20 to 40 score points, or individual risk values >= 80 only with an approved exception and a scheduled action; Red: overall value > 40 score points or >= 1 critical public resource (individual risk value >= 80) without controls/action', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (63, 63, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (64, 64, 'default', 'Target: score = 0 (no open IAM misconfigurations); Amber: score > 0 and no finding with a contribution >= 50 (exclusively non-critical findings); Red: at least one open finding with a contribution >= 50 (a critical misconfiguration open)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (65, 65, 'default', 'Target: 0 overprivileged critical admin roles (weight class 1.0) and a value not rising versus the previous period; Amber: 0 overprivileged critical admin roles, but a value rising versus the previous period; Red: at least one overprivileged critical admin role', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (66, 66, 'default', 'Target: 0 open KEV/critical findings in production outside the remediation SLA and the score not rising versus the previous period; Amber: at least one finding exceeds the SLA deadline by up to 25%, or the score rises versus the previous period; Red: at least one finding exceeds the SLA deadline by more than 25%, or a KEV-listed finding is open outside the SLA. The SLA gates act as absolute overrides; the score itself is assessed via the comparison with the previous period and additionally serves prioritization.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (67, 67, 'default', 'Target: 0% (no confirmed secrets); Amber: >0% and <0.5%, exclusively non-critical secrets, all rotated in <24 h; Red: all remaining cases — a rate >=0.5%, at least one exposure not rotated in <24 h, or every unrotated critical secret (an absolute override regardless of the rate)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (68, 68, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (69, 69, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (70, 70, 'default', 'Target: <2%; Amber: 2-5%; Red: >5%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (71, 71, 'default', 'Target: <30 for critical workloads; Amber: 30-60; Red: >60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (72, 72, 'default', '100% substantiated attestations; no unsupported representation', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (73, 73, 'default', 'Target bands for the primary reported value (composite score, score points 0-100): Target (Green) >=90; Amber 75 to <90; Red <75 — derived from the risk appetite statement of the domain (no unsteered, non-migratable cryptography in scope), conservatively aligned to the gate value 90. Additional gates on subscores: subscore_inventorying >=90 (>=90% inventorying within 6 months from the program start documented in the versioned scope document, permanently thereafter; 100% for tier-0/high-value assets); subscore_migration = 100 (no unsupported cryptography without a migration plan). A breached gate limits the reported status to Red regardless of the composite value; the numeric score remains unchanged.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (74, 74, 'default', '100% for regulated/highly sensitive holdings; >=98% for sensitive stores in scope', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (75, 75, 'default', '>=95%; crown jewel data stores =100%; freshness of the last run <=30 days', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (76, 76, 'default', '>=95%; regulated/crown jewel =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (77, 77, 'default', '<=5% (Amber >5% to <=10%, Red >10%; risk-appetite-bound, to be calibrated and documented locally); hard gate: 0 publicly exposed regulated data', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (78, 78, 'default', '>=90%; regulated/crown-jewel channels =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (79, 79, 'default', 'Overall value (count): a falling or stable trend versus the previous period; an increase = Amber, requiring explanation; Red is risk-appetite-bound, to be calibrated and documented locally; hard gate: 0 for regulated/crown jewel; every P0/P1 with an RCA and control fix', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (80, 80, 'default', '>=95%; tier-0/customer data =100%; expired/unknown owner =0 (a separate absolute gate: the number of expired or ownerless keys, reported as its own count alongside the rate)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (81, 81, 'default', '>=95%; regulated data =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (82, 82, 'default', '>=95%; crown jewel =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (83, 83, 'default', '100% for crown-jewel/regulated data flows; freshness <=90 days', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (84, 84, 'default', '>=95%; no unmasked regulated data without an exception', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (85, 85, 'default', '>=90%; crown jewel attack paths =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (86, 86, 'default', '>=90%; P0 detections =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (87, 87, 'default', 'P0 rules: P50 <=30 days; P1: P50 <=90 days; stale P0 (rule_age_days > 30, per rule) =0', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (88, 88, 'default', '>=95%; P0/P1 =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (89, 89, 'default', '>=95%; material incidents =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (90, 90, 'default', '>=85%; P0/P1 under-classification =0', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (91, 91, 'default', '>=80% per quarter; P0 scenarios =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (92, 92, 'default', 'Median <14 days; P90 <30 days; emergency threat <72h', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (93, 93, 'default', '>=95%; destructive/high-impact actions =100% approval/rollback', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (94, 94, 'default', 'P0/P1 =100%; P2 >=90%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (95, 95, 'default', '100% for regulated/material scenarios; tabletop exercise <=12 months', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (96, 96, 'default', '>=90%; repeated critical root cause =0', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (97, 97, 'default', '>=80% per quarter; P0 hypotheses = 100%. The gate is assessed per quarter; monthly values serve as an interim state without their own gate.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (98, 98, 'default', '<5%; critical recurrence = 0', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (99, 99, 'default', '>=95%; 100% for P0/P1 detections; silent critical rules require a documented exception or test evidence', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (100, 100, 'default', 'Target: >75; Amber: 60-75; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (101, 101, 'default', 'Target: 0 (no active threat); every value > 0 requires explanation in the situational picture.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (102, 102, 'default', 'Target: 0 (no open security debt). Trend guidance for the situational picture: a decline versus the previous period = on plan; a change within ±1 score point versus the previous period = stable and requiring explanation; an increase by more than 1 score point = a warning signal with submission to the exception review. A standalone RAG status is not assigned; RAG thresholds are inherited per the threshold mode from the referencing main card (STD-001).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (103, 103, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (104, 104, 'default', 'Target: expected/mean ALE <= the risk appetite; Amber: expected/mean ALE up to 10% above the appetite; Red: expected/mean ALE more than 10% above the appetite. The authoritative statistic for the appetite comparison is exclusively expected/mean; P50, P90, and P(ALE > risk appetite) are mandatory accompanying context (the tail view) but do not change the status.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (105, 105, 'default', 'Target: all top-5 services with an owner and action and without an unexplained rise of service_risk_raw versus the previous period; Amber: a top-5 service without an action or with a rising service_risk_raw without a backed action; Red: a top-5 service without an owner or without a documented decision.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (106, 106, 'default', 'Target: 0 critical open; Amber: 1-2; Red: 3 or more.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (107, 107, 'default', 'Target: the plan value reached or exceeded; Amber: a plan deviation of 10-25%; Red: a plan deviation of >25%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (108, 108, 'default', 'Target: a quotient > 0 with a stable or rising trend versus the previous period and all top-5 investments with a risk reduction verified via evidence_ref; Amber: a quotient > 0 but a falling trend versus the previous period, or data confidence < 85 (uncertain evidence); Red: a quotient = 0 (no verified risk reduction in the reporting period)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (109, 109, 'default', 'Target: >85; Amber: 70-85; Red: <70', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (110, 110, 'default', 'Target: >90 score points (the weighted tier-1 effectiveness); Amber: 80-90 score points; Red: <80 score points.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (111, 111, 'default', 'Target: >95%; Amber: 85-95%; Red: <85% or a hard obligation without evidence', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (112, 112, 'default', 'Target: >85; Amber: 70-85; Red: <70 or a tier-1 service without a passed recovery test in the reporting period', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (113, 113, 'default', 'Target: CDI <100 (debt below the baseline, a falling trend); Amber: CDI 100-120 (stable up to a slight rise of at most 20% above the baseline); Red: CDI >120 (a strong rise) or at least one critical debt individual position (an overdue component of the highest criticality class)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (114, 114, 'default', 'Target: P90 <30d; critical <7d; Amber: P90 30-60d; Red: P90 >60d or critical >7d', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (115, 115, 'default', 'Target: >85; Amber: 70-85; Red: <70', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (116, 116, 'default', 'Target: >plan (the actual value above plan_value_pct of the period); Amber: a plan deviation of 10-25%; Red: a plan deviation of >25%. Plan deviation = (plan_value_pct - the actual value) / plan_value_pct * 100; plan_value_pct is the versioned plan value per reporting period.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (117, 117, 'default', 'Target (Green): >= 95% coverage AND the hard gate met (0 exploitable unmanaged paths to crown jewels/tier-0) AND the monthly review of the top attack paths proven. Amber: >= 85% and < 95% coverage with the hard gate met, or the hard gate met but the review evidence missing in the reporting month (missing review evidence caps the status at most Amber, regardless of the coverage value). Red: < 85% coverage or >= 1 exploitable unmanaged path to crown jewels/tier-0 (a breach of the hard gate dominates the percentage bands). The bands must be approved against the risk appetite statement of the organization and documented locally with versioning.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (118, 118, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (119, 119, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (120, 120, 'default', 'Target: no expired acceptances, in particular no expired critical acceptances; Amber: at least one expired, non-critical acceptance with an overdue status of <30d; Red: at least one acceptance with an overdue status of >30d or an expired critical acceptance (critical). The RAG assignment is case-based; P50/P90 of the age values are reported supplementarily as a trend quantity.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (121, 121, 'default', 'Target: no critical exception (residual risk level 4 per the reference rubric in Part I) active and the index value not rising versus the previous period; Amber: the index value rising versus the previous period, or a critical exception with a valid expiry date and an effective compensating control; Red: at least one critical exception without an expiry date or without an effective compensating control (age_factor = 1.0 or compensating_control_gap = 1.0).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (122, 122, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (123, 123, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (124, 124, 'default', 'Target: >70%; Amber: 50-70%; Red: <50%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (125, 125, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (126, 126, 'default', 'Target: critical <7d; P90 <30d; Amber: P90 30-60d; Red: P90 >60d or critical >7d', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (127, 127, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (128, 128, 'default', 'Target: 100%; Amber: >=95% and <100%, where every non-compliant device is covered by a documented, time-limited exception; Red: <95%, or >=95% with at least one device not covered by a documented exception, or any device with sensitive data without FDE', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (129, 129, 'default', 'Target: >75; Amber: 60-75; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (130, 130, 'default', 'Target: >40%; Amber: 20-40%; Red: <20%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (131, 131, 'default', 'Target: <5%; Amber: 5-12%; Red: >12%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (132, 132, 'default', 'Target: >3.0; Amber: 1.0-3.0; Red: <1.0', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (133, 133, 'default', 'Target: <10 min; Amber: 10-30 min; Red: >30 min', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (134, 134, 'default', 'Target: <2%; Amber: 2-5%; Red: >5%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (135, 135, 'default', 'Target: >80%; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (136, 136, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (137, 137, 'default', 'Target: >90%; Amber: 70-90%; Red: <70%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (138, 138, 'default', 'Target: 0%; Amber: >0% and <2%, provided no input of strictly confidential data was detected in the reporting period; Red: >=2% or at least one detected input of strictly confidential data', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (139, 139, 'default', '>=98%; 100% for privileged, non-expiring, or cross-system identities', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (140, 140, 'default', 'Target: 100% without an open exception; Amber: 95-100% with a documented exception; Red: <95% or an admin without MFA. The check order: Red before Amber before Target; 100% counts as the target only without an open exception.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (141, 141, 'default', 'Target: >90%; Amber: 70-90%; Red: <70%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (142, 142, 'default', 'Target: a score = 0 - no dormant privileged accounts, in particular 0 critical; Amber: no Red criterion, but a score > 0 (only non-critical findings); Red: at least one critical privileged account (the highest privilege class per privilege_level) inactive for >30 days. The check order: Red before Amber before Target.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (143, 143, 'default', 'Target: 0 open deviating assignments of the risk class "critical" (admin/highly privileged rights), the risk-weighted overall value not rising versus the previous period, and all open deviations with a documented exception; Amber: no critical deviation, but the overall value rising versus the previous period or at least one open deviation without a documented exception; Red: >= 1 deviating assignment of the risk class "critical" (incl. admin rights) open at the as-of date', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (144, 144, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (145, 145, 'default', 'Target: >90%; Amber: 70-90%; Red: <70%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (146, 146, 'default', 'Target: >90%; Amber: 70-90%; Red: <70%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (147, 147, 'default', 'Target: an overall value <= 20 score points and no external user with an individual risk value >= 80 (a critical guest); Amber: an overall value > 20 up to 40 score points, or at least one individual risk value >= 80 with a documented compensation/action (no case without a control); Red: an overall value > 40 score points, or >= 1 external user with an individual risk value >= 80 without a documented control/action', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (148, 148, 'default', 'Target: 0 (no accounts/apps with allowed legacy authentication, in particular 0 privileged/external); Amber: an overall value > 0, but exclusively non-privileged, non-external accounts/apps and every case with a documented exception; Red: >= 1 privileged or external account or >= 1 critical app with allowed legacy authentication, or >= 1 case without a documented exception', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (149, 149, 'default', 'Target: a weighted overall value = 0 (no open hits against toxic_combination_rules); Amber: an overall value > 0, all open hits with a documented action/exception, and hits of the criticality class "critical" only with a scheduled action; Red: >= 1 hit of the class "critical" without a scheduled action, or >= 1 open hit without a documented action/exception', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (150, 150, 'default', '100%; every late report = a P0 exception and post-incident control failure', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (151, 151, 'default', 'Target: >90%; Amber: 60-90%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (152, 152, 'default', 'Target: >= 0 pp; Amber: -10 pp up to below 0 pp; Red: < -10 pp (the mean measure delta in percentage points)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (153, 153, 'default', 'Target: >80; Amber: 60-80; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (154, 154, 'default', 'Target: a value in the top quartile (>= P75) of the values of the measure portfolio of the same data state; Amber: a value below the top quartile (< P75) and verified_risk_reduction > 0; Red: verified_risk_reduction = 0 (no provable benefit despite a performed verification). Non-verifiable cases are n/a per the gates, not Red.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (155, 155, 'default', 'Target: P90 <14d; Amber: 14-30d; Red: >30d', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (156, 156, 'default', 'Target: Benefit Lag <= the expected_benefit_window_days of the measure (the effect in the expected effect window); Amber: an effect observed, but Benefit Lag > expected_benefit_window_days (the effect late); Red: no measurable effect and the as-of date - measure_completed_at > expected_benefit_window_days (no effect after the effect window has elapsed). Measures without an observed effect within the effect window (the as-of date - measure_completed_at <= expected_benefit_window_days) are not yet assigned to a band (status: pending) and do not enter the traffic light. Aggregation to the card status: worst-wins across all assessed measures in scope — at least one measure Red -> the card status Red; otherwise at least one measure Amber -> the card status Amber; otherwise Target.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (157, 157, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (158, 158, 'default', 'Target: >90%; Amber: 70-90%; Red: <70%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (159, 159, 'default', 'Target: <5%; Amber: 5-15%; Red: >15%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (160, 160, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (161, 161, 'default', '>=95%; Tier-0/ZTNA/admin paths =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (162, 162, 'default', 'Red: >=1 critical unauthorized rule or >=1 expired exception. Amber: 0 critical unauthorized rules and 0 expired exceptions, but a drift rate > 0% or a rising trend. Green: a drift rate = 0% (0 critical unauthorized rules; 0 expired exceptions).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (163, 163, 'default', '>=95%; Tier-0/Tier-1 =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (164, 164, 'default', '>=99%; privileged remote sessions =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (165, 165, 'default', '>=90%; sensitive segments =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (166, 166, 'default', '>=95%; Tier-0/Tier-1 =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (167, 167, 'default', 'Gates: 100% of primary domains conformant; p=reject for productive sending domains; 0 unknown senders (sending sources in the DMARC aggregate reports of the reporting period that cannot be assigned to any sending source authorized in the domain inventory — a separate side condition from the DMARC reports, not from the numerator/denominator). The RAG band for the reported overall coverage: Green = all gates met and an overall coverage = 100%; Amber = all gates met, but an overall coverage < 100%; Red = at least one gate violated (a primary domain not conformant, a productive sending domain without p=reject, or >=1 unknown sender).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (168, 168, 'default', 'The escape rate (%): the Green/Amber/Red band is derived risk-appetite-bound from the local risk-appetite statement and documented with versioning (threshold_mode risk_appetite_bound); without a documented band, no Green. Additional conditions for Green: a falling trend; for every critical escape, an RCA completed <=5 working days (a process condition, proof via the SOAR case/evidence ref, not part of the formula).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (169, 169, 'default', '<1%; 0 in sensitive segments', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (170, 170, 'default', '>=95%; Tier-0/Tier-1 =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (171, 171, 'default', '100% for critical/important functions; no resilience sign-off without a dependency map', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (172, 172, 'default', '100% Tier-0/safety-critical coverage; >=95% overall coverage; no unknown, unmanaged OT segment', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (173, 173, 'default', '>=95%; 100% for high-risk processing and special data categories', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (174, 174, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (175, 175, 'default', 'Target: >85; Amber: 70-85; Red: <70', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (176, 176, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (177, 177, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (178, 178, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (179, 179, 'default', 'Target: >85; Amber: 70-85; Red: <70', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (180, 180, 'default', 'Target: >80; Amber: 60-80; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (181, 181, 'default', 'Target: no critical untested dependency (no individual record with service_criticality >= 8 and test_gap = 1.0), no individual contribution >= 2.0 risk points, and the sum value falling or stable versus the prior period; Amber: a moderate gap (no critical untested dependency, but at least one individual contribution >= 2.0 risk points or a sum value rising versus the prior period); Red: a critical untested dependency (at least one individual record with service_criticality >= 8 and test_gap = 1.0). The precedence rule: worst-wins — if more than one condition applies, the worst band applies (Red before Amber before Target).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (182, 182, 'default', 'Target: falling; no Tier-1 debt (the value falls versus the prior period and no debt individual record concerns a Tier-1 service, service_tier = 1 = the highest criticality level); Amber: moderate debt (no Tier-1 debt individual record, but the value stagnating or rising); Red: Tier-1 recovery debt (at least one debt individual record for a Tier-1 service)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (183, 183, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (184, 184, 'default', '100% of the critical services (the denominator excluding formally approved, time-limited exceptions; exceptions reported separately); currency: the last BIA review <=12 months back AND no major change occurred since then that has not yet been followed up by a re-validation (a major change invalidates the BIA until the re-validation)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (185, 185, 'default', '100% of the demanded recovery tests with the full depth (the integrated service, data integrity, security validation, business acceptance) and business-owner acceptance; the test frequency: critical services annually one integrated recovery test, Tier-0 semiannually', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (186, 186, 'default', '>=90% in the introduction phase; Tier-0/Tier-1 = 100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (187, 187, 'default', 'A 0% gap for Tier-0/Tier-1, checked per Tier-0/Tier-1 service; the overall gap: within the locally documented gap budget approved in the risk appetite — an overrun is Amber with a measure, owner, and deadline; a Tier-0/Tier-1 gap above 0 or an overall gap above the budget without a measure is Red; a quarterly review', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (188, 188, 'default', '>=98%; executive/crisis-team roles = 100%; the contact test <=90 days back', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (189, 189, 'default', '>=80% in the introduction phase; life/safety/regulatory-critical processes = 100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (190, 190, 'default', 'The uncovered exposure within the approved risk appetite; a review annually or on a material change', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (191, 191, 'default', '100% of the critical backup platforms; no shared admin path to the production domain', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (192, 192, 'default', 'The drift rate (the metric value): a risk-appetite-bound band — Green if the drift rate lies at or below the target value documented in the risk appetite and released with versioning; Amber if it exceeds the target value without a gate being violated; Red on a gate breach. The gate population (inventory-based): all undocumented dependency changes of critical services open at the as-of date (the period end), including legacy cases from earlier reporting periods. Gate 1 (hard): 0 open undocumented Tier-0 dependency changes older than 30 days — every such change is a gate breach (Red). Gate 2 (an additional gate at the individual-case level): the p95 of the age of the non-carryover in days, measured over this inventory, <60 days. The status logic: Green only if the drift rate lies in the target range, both gates are met, and the data confidence suffices.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (193, 193, 'default', 'P0/P1 services = 100% (the gate). The status logic: Red as soon as at least one P0/P1 recovery was handed over to the business without a fully passed, evidence-backed security validation; Green only with a P0/P1 value = 100% and sufficient data confidence. The overall value across all validation-required recoveries is reported as a context and trend value without its own RAG band.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (194, 194, 'default', '>=95%; tier-0/tier-1 >=98%; critical deviations = 0. A critical deviation = an open deviation from the approved baseline not covered by a valid approved exception whose check rule is classified in the baseline as the severity critical; the source: the CIS benchmark scanner or CSPM, counted as a piece count per asset-check-rule pair from the same case base as the numerator and denominator.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (195, 195, 'default', 'The p95 <30 days (nearest rank over all open drifts in scope); tier-0 critical <7 days (the maximum age per individual case: every open drift with the drift severity critical on a tier-0 asset, no percentile statistic)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (196, 196, 'default', 'The rate (the share expired/near_expiry/unapproved) overall sinking in the trend; the additional gates from the same case base: expired or unapproved exceptions = 0 (0 expired); tier-0: the maximum age of an open exception 14 days (checked per individual case)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (197, 197, 'default', '>=98%; Tier-0 =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (198, 198, 'default', '>=95%; the additional gate: every tier-0 emergency change is validated afterwards <=48h (per individual case: post_change_validation_timestamp minus change_implemented_timestamp <= 48 hours)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (199, 199, 'default', '>=98%; tier-0/tier-1 =100%; no internet-facing gap', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (200, 200, 'default', '>=98%; tier-0/tier-1 =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (201, 201, 'default', '>=95%; critical test cases =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (202, 202, 'default', '>=95%; tier-0/tier-1 >=98%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (203, 203, 'default', '>=95%; sensitive areas/tier-0 =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (204, 204, 'default', '>=98% the target (Green); 100% for crown-jewel/tier-0 systems; 95% to <98% Amber; <95% Red (no board Green)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (205, 205, 'default', '>=99% for tier-0/tier-1; >=97% overall', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (206, 206, 'default', '>=95% overall; 100% for identity/admin/cloud-control-plane/security-tool events', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (207, 207, 'default', '>=95%; >=98% for P0 sources', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (208, 208, 'default', 'The overall score >=95 points and all source-class gates fulfilled (Green); the overall score >=95 points with at least one breached source-class gate (Amber); the overall score <95 points (Red). The source-class gates: >=97 points per P0 source class, >=95 points per P1 source class.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (209, 209, 'default', '>=99%; 100% for tier-0/tier-1', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (210, 210, 'default', '100% for regulatorily/forensically mandatory classes; >=95% overall', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (211, 211, 'default', '>=95%; 100% for tier-0, the cloud control plane, IAM, EDR/SIEM audit logs', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (212, 212, 'default', '<0.5% for P0 sources; <1% overall; every unclarified zero emission critical', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (213, 213, 'default', '>=98%; 100% for tier-0/tier-1', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (214, 214, 'default', 'The p95 <14 days; the max <30 days; the tier-0 max <7 days', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (215, 215, 'default', '>=90% for top threat scenarios; 100% for tier-0 kill-chain blockers', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (216, 216, 'default', '>=70% within 90 days from the first measurement of the metric in the respective scope; sources without a benefit: keep, improve, or switch off', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (217, 217, 'default', '>=95% per month; 100% for P0 use cases', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (218, 218, 'default', 'No expired open exceptions; the weighted score with a sinking trend; tier-0 exceptions <=7 days', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (219, 219, 'default', 'The trend sinking with the same or a rising coverage per LOG-010 (Security Sensor Health Coverage) and LOG-012 (ATT&CK Data Source Coverage for Priority Threats) in the same scope; no target traffic light without these quality gates', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (220, 220, 'default', '>=95% scope coverage; 100% of the due high/critical findings closed verified on deadline or formally risk-accepted before the due date; no unmanaged critical finding', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (221, 221, 'default', 'Target: 100% coverage of the TLPT-obligated entities at the as-of date (the last calendar day of the reporting quarter). The additional gates, each checkable from the minimum data fields: (a) no overdue TLPT cycle — overdue = tlpt_cycle_due_date < the as-of date and no tlpt_test_completion_date in the running cycle; (b) no critical TLPT finding without an owner — every finding with finding_severity = critical must carry a filled owner_id and an active remediation_status. Every gate breach sets the status to Red independently of the percentage value.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (222, 222, 'default', 'Target: >70% for relevant cases; Amber: 40-70%; Red: <40%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (223, 223, 'default', 'Target: >70; Amber: 40-70; Red: <40', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (224, 224, 'default', 'Target: context-dependent: a high value can show awareness or a detection gap; Amber: a deviation >25% from the baseline; Red: a rise for critical incidents without technical detection', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (225, 225, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (226, 226, 'default', 'Target: CSAT >4/5 or NPS >30; Amber: CSAT 3.5-4 or NPS 0-30; Red: CSAT <3.5 or NPS <0. The CSAT bands apply to the 5-point scale; with a deviating versioned scale, they must be normalized equivalently to it. Decisive is the band series of the locally versioned variant (CSAT or NPS).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (227, 227, 'default', 'Target: >80; Amber: 60-80; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (228, 228, 'default', 'Target: >80%; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (229, 229, 'default', 'Target: the reporting time per case within the versioned sla_deadline of the reporting-obligation class (the internal/regulatory SLA; NIS2/DORA where in scope), and the assessment quantity is the P90 per reporting-obligation class; Amber: the P90 exceeds the SLA by up to 10% and no SLA violation of a case with a regulatory reporting obligation; Red: at least one SLA violation of a case with a regulatory reporting obligation or the P90 > the SLA +10%. Red takes precedence over Amber.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (230, 230, 'default', 'Target: >85%; Amber: 65-85%; Red: <65%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (231, 231, 'default', 'Target: >80%; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (232, 232, 'default', 'Target: the median < 24h; the P90 < 7d; adjust per severity; Amber: the median 24-72h or the P90 7-14d; Red: the median >72h or the P90 >14d', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (233, 233, 'default', 'Target (Green): the P50 for high/critical incidents below the locally documented target value (1h-4h per the target picture); set and report the P90 target separately. Amber: the P50 or P90 reaches or exceeds the respective target up to and including the target +50%; overruns of more than 25% must be justified separately in the report. Red: the P50 or P90 exceeds the respective target by more than 50%, or the data quality <70. The overall status = the worst band of the separately assessed quantities.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (234, 234, 'default', 'Target (Green): critical: MTTC < 4h and MTTR < 24h; document the targets per service criticality locally. Amber: MTTC or MTTR reaches or exceeds the respective target up to and including the target +50% (e.g. MTTR 24h to 36h with a target of 24h); overruns of more than 25% must be justified separately in the report. Red: an overrun of the respective target by more than 50% (e.g. MTTR > 36h with a target of 24h). The overall status = the worst band of the separately assessed quantities.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (235, 235, 'default', 'Target: >80% for relevant incident classes; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (236, 236, 'default', 'Target: >85% of the relevant TTP scenarios; Amber: 65-85%; Red: <65%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (237, 237, 'default', 'Target: >95% technical detection of the simulation base population; Amber: 85-95% (a value of exactly 95% falls into Amber, since the target demands >95%); Red: <85%. The RAG assessment applies to the simulation rate; the rate of confirmed real phishing attempts must be reported separately as a reporting quantity without its own RAG band.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (238, 238, 'default', 'Target: >90% for defined data classes and channels; Amber: 70-90%; Red: <70%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (239, 239, 'default', 'Target (Green): a 20-40% finding rate (the bounds included); supplementarily, per finding, the validation status with evidence (finding_validation_status, evidence_ref) must be reported. Amber: 10% to under 20%; above 40% up to and including 60%; above 60% (here additionally a mandatory tuning/scope review documented with versioning — the criterion ''without tuning'' counts as met if this proof is missing in the reporting period, and it must then be reported to the escalation owner); as well as a single quarter under 10%. Red: under 10% in two consecutive quarters.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (240, 240, 'default', 'Target: >85; Amber: 70-85; Red: <70', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (241, 241, 'default', 'Target: >80; Amber: 65-80; Red: <65', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (242, 242, 'default', 'Target: >75%; Amber: 50-75%; Red: <50% — assessed is the share of correctly correlated alerts/cases with a validated security relation among all correlated alerts/cases of the scope and reporting period (identical to the formula denominator).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (243, 243, 'default', 'Target (the P50 per severity): critical < 4h, high < 8h; Amber: above the target up to and including the target +50% (critical 4-6h, high 8-12h); Red: above the target +50% (critical > 6h, high > 12h). The P90 is reported as the mandatory companion value.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (244, 244, 'default', 'Target: >70%; Amber: 50-70%; Red: <50% — assessed is the rate over the entire formula denominator: the performed scenarios of the versioned test library plus the validated real cases of the reporting period.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (245, 245, 'default', 'A separate report per subset. Known malware: the target >95%; Amber: 80-95%; Red: <80%. Test-based TTPs: the target >80%; not reached (<=80%) = Red (a binary band without Amber). A mixed overall rate is not assessed against the bands.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (246, 246, 'default', 'Target: >90%; Amber: 70-90%; Red: <70% — all bands refer exclusively to the simulation subset of the denominator. Real confirmed cases do not run into the banded rate but are reported individually.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (247, 247, 'default', 'Target: >70%; Amber: 50-70%; Red: <50% — the bands refer exclusively to the subset of the defined test scenarios. Confirmed real insider cases do not run into the banded rate but are reported individually; a mixed overall rate is not assessed against the bands.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (248, 248, 'default', 'Target: >70% for escalation-capable alerts; Amber: 40-70%; Red: <40%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (249, 249, 'default', 'Target: >95% for the defined policy scope; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (250, 250, 'default', 'Target: >80% with an acceptable FP load; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (251, 251, 'default', 'Target: a sinking trend without a quality loss; benchmark per severity; Amber: the costs per incident +20% versus the versioned baseline; Red: the costs per incident +50% versus the versioned baseline or an MTTR increase versus the MTTR reference value of the baseline period. The baseline = the versioned cost-per-incident reference value with the baseline value, baseline period, baseline scope, and baseline version as the mandatory context of the result; MTTR = the median of the span detected_at to contained_at/resolved_at of the confirmed incidents in the respective period with an identical scope.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (252, 252, 'default', 'Target: >40% in the MVP scope; >70% for repetitive triage; Amber: 20-40%; Red: <20%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (253, 253, 'default', 'Target: <30; Amber: 30-60; Red: >60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (254, 254, 'default', 'Target: <30% relative to all checked alerts (total_alerts_reviewed), escalated alerts included; Amber: 30-50%; Red: >50%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (255, 255, 'default', 'Target: <10% as the overall rate; per use case, a stricter local target in the range 5-10% must be set versioned and assessed in the drilldown; Amber: 10-20%; Red: >20%. The RAG assignment of the reported overall rate is made deterministically against the bands <10% / 10-20% / >20%.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (256, 256, 'default', 'Target: <5%; Amber: 5-10%; Red: >10%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (257, 257, 'default', 'Target: internet-facing critical/KEV <=72h; for internal classes, the SLA threshold is the deadline per severity/exposure class locally derived from the risk appetite and documented versioned; Amber: the SLA threshold of the class +25%; Red: the SLA threshold of the class +50% or the KEV SLA (<=72h) violated. Checked is the P90 (nearest rank) per severity/exposure class against the respective SLA threshold; the P50 is reported supplementarily.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (258, 258, 'default', 'Target: 65-80% (the bounds 65% and 80% inclusive); Amber: 50% to <65% or >80% to 90%; Red: <50% or >90%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (259, 259, 'default', 'Target: critical <30min, high <2h; Amber: above the target up to and including the target +50% (critical 30-45min, high 2-3h), with an early-warning threshold within Amber from the target +25% (critical 37.5min, high 2.5h) that triggers a commenting duty but does not change the traffic light; Red: above the target +50% (critical >45min, high >3h). Checked is the P90 (nearest rank) per severity against the target time; the P50 is reported supplementarily.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (260, 260, 'default', 'Target: context-dependent; no isolated good/bad; Amber: a deviation >25% from the baseline (the median of the escalation counts of the last 6 completed reporting periods of the same length, an identical scope, versioned); Red: a deviation >50% from the baseline or at least one critical escalation exceeds the target time of 30 minutes (escalated_at - detected_or_triaged_at, consistent with the MTTE card)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (261, 261, 'default', 'Target: >90% (resolved within the SLA deadline with closure evidence); Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (262, 262, 'default', 'Target: critical <15min, high <30min; Amber: the target +25%; Red: the target +50%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (263, 263, 'default', 'Target: the net effect per quarter positive and at least the expected benefit -25% (the expected benefit = expected_net_benefit, the versioned expected quarterly net effect from the automation business case); Amber: the net effect 0 to under the expected benefit -25%; Red: the net effect negative or the quality deteriorated', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (264, 264, 'default', 'Target: >80; Amber: 65-80; Red: <65', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (265, 265, 'default', 'Target: >80; Amber: 60-80; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (266, 266, 'default', 'Target: no RTO overrun (the downtime per interruption <= rto_minutes of the affected service from the versioned service catalog) and the weighted minute sum versus the prior period sinking or stable; Amber: no tier-1 RTO overrun, but at least one RTO overrun at non-critical services (service_tier >= 2) or the weighted minute sum versus the prior period rising; Red: at least one RTO overrun at tier-1 services (service_tier = 1) or an interruption with regulatory_impact_flag = true.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (267, 267, 'default', 'Target: >80; Amber: 60-80; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (268, 268, 'default', 'Target: >70%; Amber: 50-70%; Red: <50%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (269, 269, 'default', 'Target: >70%; Amber: 40-70%; Red: <40%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (270, 270, 'default', 'Target: >80; Amber: 60-80; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (271, 271, 'default', 'Target: 5-15% per the maturity level; Amber: >0% and <5%, >15% and <=20%, or >20% with a documented impact measurement (impact_evidence_ref set); Red: 0% or >20% without a documented impact measurement (impact_evidence_ref not set)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (272, 272, 'default', 'Target: >60%; Amber: 40-60%; Red: <40%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (273, 273, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (274, 274, 'default', 'Target: 90-110%; Amber: 75-90% or 110-125%; Red: <75% or >125%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (275, 275, 'default', 'Target: the score >75 (corresponding to a CV <0.25 with a target CV of 0 and worst CV of 1.0); Amber: the score 60-75 (corresponding to a CV of 0.25-0.4); Red: the score <60 (corresponding to a CV >0.4)', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (276, 276, 'default', 'Target: <15% annualized (a rolling 12-month rate); Amber: 15-25% annualized; Red: >25% annualized', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (277, 277, 'default', 'Target: the target maturity per service class, set as a target score on the 0-100 scale; Amber: up to 25 score points (= 1 maturity level) below the target score; Red: more than 25 score points (> 1 maturity level) below the target score', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (278, 278, 'default', 'Target: >80; Amber: 60-80; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (279, 279, 'default', 'Target: >80%; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (280, 280, 'default', 'Target: 65-80% (the bounds 65% and 80% inclusive); Amber: 50% to <65% or >80% to 90%; Red: <50% or >90%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (281, 281, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (282, 282, 'default', 'Target: 100% coverage for the critical 24x7 scope; every uncovered critical service hour counts as an exception. For non-critical required hours, locally documented thresholds per the threshold mode apply.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (283, 283, 'default', 'Target: >80%; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (284, 284, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (285, 285, 'default', 'Target: >95%; Amber: 85-95%; Red: <85% — assessed on the formula rate over all applicable requirements; the partial rate of the binding requirements (requirement_type = binding) must be reported alongside for information.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (286, 286, 'default', 'Target: >95% for high/critical; Amber: 80-95%; Red: <80%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (287, 287, 'default', 'Target: <=10 working days; Amber: >10 to 20 working days; Red: >20 working days — assessed on the P50 of the RCA times for high/critical incidents; the conversion: 1 working day = 8 hours per the versioned operating calendar (Mon-Fri without local holidays).', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (288, 288, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (289, 289, 'default', 'Target: >75 and positive trends; Amber: 50-75; Red: <50', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (290, 290, 'default', 'Target: >90%; Amber: 75-90%; Red: <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (291, 291, 'default', 'Target: >80% in the defined scope; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (292, 292, 'default', 'Target: >95% or 100% for hard obligations; Amber: 85-95%; Red: <85% or a hard obligation open', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (293, 293, 'default', '100% critical suppliers; >=95% all high-risk suppliers', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (294, 294, 'default', 'The overall base >=95%; critical providers = 100%; stale evidence = 0 beyond the freshness SLA', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (295, 295, 'default', '>=90%; no critical supplier risk above the appetite without an executive decision', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (296, 296, 'default', '>=95%; new critical contracts = 100% before the signature', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (297, 297, 'default', '>=95%; critical service providers = 100%; the contact test <=6 months', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (298, 298, 'default', 'No single unmanaged concentration above the appetite (the value = 0%); a quarterly review', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (299, 299, 'default', '>=80% initially; services marked as DORA-relevant =100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (300, 300, 'default', '>=90%; MDR/MSSP/cloud control plane = 100%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (301, 301, 'default', '100% critical/privileged third-party accesses; expired accesses = 0', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (302, 302, 'default', '>=90%; critical findings above the SLA without an escalation = 0', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (303, 303, 'default', '>=98%; 100% for critical/important functions and material outsourcing', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (304, 304, 'default', 'The index <= 100 index points (no rise versus the versioned baseline = the target); every value > 100 must be explained and triggers a board review for the causing top concentration exposures. The additional qualitative gate per exposure: no unmanaged critical single-provider concentration; a board review for top concentration exposures.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (305, 305, 'default', '>=90% within the SLA; 100% with active campaigns against the own sector/tech stack', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (306, 306, 'default', 'Target: >70%; Amber: 40-70%; Red: <40%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (307, 307, 'default', 'Target: >70%; Amber: 50-70%; Red: <50%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (308, 308, 'default', 'Target: >80; Amber: 60-80; Red: <60', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (309, 309, 'default', 'Target: >85%; Amber: 65-85%; Red: <65%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (310, 310, 'default', 'Target: >80%; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (311, 311, 'default', 'Target: >70% of the relevant feeds; Amber: 40-70%; Red: <40%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (312, 312, 'default', 'Target: >80%; Amber: 60-80%; Red: <60%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (313, 313, 'default', 'Target: per the risk appetite; the critical exposure <72h if internet-facing; Amber: the SLA +25%; Red: the SLA +50% or Critical above the appetite', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (314, 314, 'default', 'Target: >75%; Amber: 55-75%; Red: <55%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (315, 315, 'default', 'Target: the precision >70%, the recall >90% for KEV/Critical; Amber: the precision 50-70% or the recall 75-90%; Red: the precision <50% or the recall <75%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (316, 316, 'default', '>=95% overall; 100% for internet-facing/tier-0 within the defined cadence; no stale critical asset', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (317, 317, 'default', '>=95% overall; >=99% for critical security patches on managed assets; failed critical patches triaged within 24h', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (318, 318, 'default', 'Target: a sinking trend of the risk-weighted hour sum versus the immediate prior period; per individual finding, the SLA applies, for Critical internet-facing open_hours <=72h; Amber: a rise of the hour sum >20% versus the prior period or an individual finding above the SLA up to +25%; Red: a rise of the hour sum >50% versus the prior period, an individual finding above the SLA +50%, or KEV overdue', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (319, 319, 'default', 'Target: 0 open outside the emergency window (no open KEV combination older than the emergency window of 72 hours from detected_at); Amber: 1-3 open KEV combinations outside the emergency window, all within the SLA (the remediation SLA of 14 calendar days from detected_at); Red: >3 open KEV combinations outside the emergency window or the SLA violated (at least one open combination older than the remediation SLA). The check order: Red before Amber before the target. The emergency window and SLA are versioned defaults of this card; local deviations must be documented versioned.', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (320, 320, 'default', 'Target: a sinking trend versus the immediate prior period; high EPSS prioritized; Amber: a rise >20% versus the prior period; Red: a rise >50% versus the prior period or a high-EPSS finding (epss_score >= 0.5) above the remediation SLA of its risk tier', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (321, 321, 'default', 'Target: >95%; Amber: 85-95%; Red: <85% or KEV violated', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (322, 322, 'default', 'Target: per the risk tier; Amber: the SLA +25%; Red: the SLA +50%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (323, 323, 'default', 'Target: <5%; Amber: 5-10%; Red: >10%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (324, 324, 'default', 'Target: no expired exceptions (overdue_days = 0 for all open exceptions); Amber: expired with an overdueness <30d; Red: an overdueness >30d or an expired exception on a Critical finding', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (325, 325, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (326, 326, 'default', 'Target: >90%; Amber: 70-90%; Red: <70%', NULL, NULL, NULL, '2026-07-06', NULL);
INSERT INTO kpi_threshold VALUES (327, 327, 'default', 'Target: >95%; Amber: 85-95%; Red: <85%', NULL, NULL, NULL, '2026-07-06', NULL);
